// Phase 69 (CANO-02, D-03) · Phase 110-02 (D-08) per-swarm generalization.
// Codegen script: reads swarms.entity_brand from the live registry for ALL
// swarms and writes a generated TS per-swarm map + literal-union to
// web/lib/automations/debtor-email/coordinator/entity.generated.ts.
//
// Why: keeps strict TS compile-time safety AND zero-edit onboarding. After a
// new brand row is INSERTed (or a new swarm onboards) into the registry, run
// `npm run codegen` and commit the regenerated file. Operator never edits the
// .generated.ts by hand (D-06).
//
// Phase 110-02 (D-08): this script previously read a SINGLE swarm via the
// `process.env.SWARM_TYPE ?? "debtor-email"` hack and emitted a flat
// ENTITY_BRANDS tuple. It now mirrors gen-tenant-domains.ts exactly — iterate
// ALL swarms, emit ENTITY_BRANDS_BY_SWARM (a per-swarm map) plus a union-over-
// all-swarms `Entity` literal type. The map shape is safe even when a swarm
// has an empty brand set (e.g. sales-email = []) because the union over all
// swarms stays non-empty (debtor still carries its 6 brands) — the empty-union
// footgun (RQ4) is avoided.
//
// entity_brand shape note: the column is registry-historical — debtor-email is
// the post-Phase-69 jsonb-of-objects shape (each element `{code, ...}`); older
// swarms (info-routing, support-tickets) are still the legacy string-array
// seed. We read the raw column directly (like gen-tenant-domains) and extract
// the brand CODE from both shapes (object → `.code`, string → itself), so no
// swarm's codes are dropped and debtor's output stays byte-identical.
//
// Run:   npx tsx scripts/gen-entity-types.ts
// CI:    npm run codegen
//
// Idempotent: if the on-disk content already matches, prints "already
// up-to-date" and exits 0 without rewriting (preserves mtime; clean diff).

import { createClient } from "@supabase/supabase-js";
import {
  writeFileSync,
  mkdirSync,
  readFileSync,
  existsSync,
} from "node:fs";
import { dirname, resolve } from "node:path";
import { config as loadDotenv } from "dotenv";

loadDotenv({ path: resolve(__dirname, "..", ".env.local") });

const OUTPUT_PATH = resolve(
  __dirname,
  "..",
  "lib",
  "automations",
  "debtor-email",
  "coordinator",
  "entity.generated.ts",
);

const HEADER = `// AUTO-GENERATED by scripts/gen-entity-types.ts (Phase 69 / CANO-02 / D-03; Phase 110-02 / D-08 per-swarm map).
// DO NOT EDIT BY HAND. Run \`npm run codegen\` after registry changes.
//
// Source of truth: public.swarms.entity_brand (per-swarm brand register).
// Regenerate when a new brand is INSERTed or a new swarm onboards.

`;

interface SwarmEntityRow {
  swarm_type: string;
  entity_brand: unknown;
}

/**
 * Extract brand CODES from a swarm's entity_brand column, tolerating both the
 * post-Phase-69 jsonb-of-objects shape (`{code, ...}[]`) and the legacy
 * string-array seed (`string[]`). Unknown/null → empty list.
 */
function extractCodes(entityBrand: unknown): string[] {
  if (!Array.isArray(entityBrand)) return [];
  const codes: string[] = [];
  for (const elem of entityBrand) {
    if (typeof elem === "string") {
      codes.push(elem);
    } else if (
      elem &&
      typeof elem === "object" &&
      typeof (elem as { code?: unknown }).code === "string"
    ) {
      codes.push((elem as { code: string }).code);
    }
  }
  return codes;
}

function renderBody(rows: SwarmEntityRow[]): string {
  if (rows.length === 0) {
    // Defensive: an empty registry shouldn't happen in practice, but emit a
    // valid TS file anyway so the build doesn't break in dev.
    return (
      `export const ENTITY_BRANDS_BY_SWARM = {} as const;\n\n` +
      `export type Entity = never;\n`
    );
  }
  // Stable diff: sort rows by swarm_type and sort each code list alphabetically.
  const sortedRows = [...rows].sort((a, b) =>
    a.swarm_type.localeCompare(b.swarm_type),
  );
  const entries = sortedRows
    .map((r) => {
      const codes = [...new Set(extractCodes(r.entity_brand))].sort();
      const list = codes.map((c) => `"${c}"`).join(", ");
      return `  ${JSON.stringify(r.swarm_type)}: [${list}],`;
    })
    .join("\n");
  return (
    `export const ENTITY_BRANDS_BY_SWARM = {\n${entries}\n} as const;\n\n` +
    `export type Entity =\n  (typeof ENTITY_BRANDS_BY_SWARM)[keyof typeof ENTITY_BRANDS_BY_SWARM][number];\n`
  );
}

async function main(): Promise<void> {
  const url =
    process.env.SUPABASE_URL ?? process.env.NEXT_PUBLIC_SUPABASE_URL;
  const key =
    process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.SUPABASE_SERVICE_KEY;
  if (!url || !key) {
    throw new Error(
      "[gen-entity-types] SUPABASE_URL (or NEXT_PUBLIC_SUPABASE_URL) + SUPABASE_SERVICE_ROLE_KEY required",
    );
  }
  const admin = createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

  const { data, error } = await admin
    .from("swarms")
    .select("swarm_type, entity_brand")
    .order("swarm_type");
  if (error) {
    throw new Error(`[gen-entity-types] swarms query failed: ${error.message}`);
  }

  const rows: SwarmEntityRow[] = (data ?? []).map((r) => ({
    swarm_type: r.swarm_type as string,
    entity_brand: r.entity_brand as unknown,
  }));

  const next = HEADER + renderBody(rows);

  mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
  const existing = existsSync(OUTPUT_PATH)
    ? readFileSync(OUTPUT_PATH, "utf8")
    : null;

  if (existing === next) {
    console.log(
      `[gen-entity-types] already up-to-date (${rows.length} swarm rows) — no write`,
    );
    return;
  }

  writeFileSync(OUTPUT_PATH, next, "utf8");
  console.log(
    `[gen-entity-types] wrote ${rows.length} swarm rows to ${OUTPUT_PATH}`,
  );
}

main().catch((err) => {
  console.error("[gen-entity-types] FAILED:", err);
  process.exit(1);
});
